#include <Arduino.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int BTN1_PIN = 2;  
const int BTN2_PIN = 3;  
const int BTN3_PIN = 4;  
const int BARGRAPH_START = 5;  
const int BARGRAPH_COUNT = 10;
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};
int currentNumber = 0;

void setup();
void loop();
void checkButton(int pin, int increment);
void displayNumber(int num);
void updateBargraph(int num);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  pinMode(BTN1_PIN, INPUT_PULLUP);
  pinMode(BTN2_PIN, INPUT_PULLUP);
  pinMode(BTN3_PIN, INPUT_PULLUP);
  for (int i = 0; i < BARGRAPH_COUNT; i++) {
    pinMode(BARGRAPH_START + i, OUTPUT);
    digitalWrite(BARGRAPH_START + i, LOW);
  }
  displayNumber(currentNumber);
  updateBargraph(currentNumber);
}
void loop() {
  checkButton(BTN1_PIN, 1);
  checkButton(BTN2_PIN, 5);
  checkButton(BTN3_PIN, 0);
}
void checkButton(int pin, int increment) {
  if (digitalRead(pin) == LOW) {
    delay(150);
    if (digitalRead(pin) == LOW) {
      if (increment == 0) {
        currentNumber = 0;
      } else {
        currentNumber += increment;
        if (currentNumber > 99) currentNumber = 0;
      }
      displayNumber(currentNumber);
      updateBargraph(currentNumber);
      while (digitalRead(pin) == LOW);
    }
  }
}
void displayNumber(int num) {
  int tens = num / 10;
  int ones = num % 10;
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, segmentCodes[ones]);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, segmentCodes[tens]);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
void updateBargraph(int num) {
  int tens = num / 10;
  for (int i = 0; i < BARGRAPH_COUNT; i++) {
    digitalWrite(BARGRAPH_START + i, (i < tens) ? HIGH : LOW);
  }
}
